<template><view class="admin-board"><view class="board-head"><view><text class="board-kicker">ADMIN ANALYTICS</text><text class="board-title">数据大屏</text><text class="board-sub">实时业务数据总览</text></view><button class="refresh-btn" size="mini" :disabled="loading" @tap="load">刷新</button></view><text v-if="error" class="board-error">{{ error }}</text><text v-if="loading" class="board-loading">正在读取数据…</text><template v-if="overview"><view class="board-grid"><view v-for="(item,i) in metrics" :key="item.label" class="metric-card" :class="'metric-'+i"><view class="metric-icon">{{ ['人','企','岗','简'][i] }}</view><text class="metric-label">{{ item.label }}</text><text class="board-value">{{ item.value }}</text><text class="metric-caption">当前总量</text></view></view><view class="board-section chart-card"><view class="section-head"><view><text class="board-section-title">岗位趋势</text><text class="section-sub">近期开启与新增数量</text></view><text class="section-badge">TREND</text></view><svg class="line-chart" viewBox="0 0 600 220"><polyline :points="trendPoints" fill="none" stroke="#2563eb" stroke-width="8" stroke-linecap="round" stroke-linejoin="round"/><circle v-for="(p,i) in trendDots" :key="i" :cx="p.x" :cy="p.y" r="8" fill="#fff" stroke="#2563eb" stroke-width="5"/><text v-for="(p,i) in trendDots" :key="'t'+i" :x="p.x" y="210" text-anchor="middle">{{ p.label }}</text></svg><text v-if="!trend.length" class="empty-text">暂无趋势数据</text></view><view class="board-section chart-card"><view class="section-head"><view><text class="board-section-title">热门岗位</text><text class="section-sub">按业务数量排序</text></view><text class="section-badge purple">TOP</text></view><view v-for="(row,i) in jobs" :key="row.id || i" class="bar-row"><text class="rank">{{ String(i+1).padStart(2,'0') }}</text><text class="bar-label">{{ row.title || row.name }}</text><view class="bar-track"><view class="bar-fill" :style="{width: barWidth(row)+'%'}"></view></view><text class="bar-value">{{ row.count ?? row.value ?? row.views ?? 0 }}</text></view><text v-if="!jobs.length" class="empty-text">暂无岗位数据</text></view><view class="board-section chart-card"><view class="section-head"><view><text class="board-section-title">业务漏斗</text><text class="section-sub">平台业务转化概览</text></view><text class="section-badge green">FUNNEL</text></view><view v-for="(item,i) in funnelRows" :key="i" class="funnel-row"><view :style="{width:item.width+'%'}"><text>{{ item.label }}</text><text>{{ item.value }}</text></view></view></view></template></view></template>
<script setup>
import {computed,onMounted,ref} from 'vue'
import {request} from '../../utils/request'
const overview=ref(null),trend=ref([]),jobs=ref([]),funnel=ref({}),loading=ref(false),error=ref('')
const unwrap=x=>x?.data??x??{}
const scalar=v=>typeof v==='object'&&v!==null?(v.total??v.enterprise_total??v.crawled??v.count??0):(v??0)
const metrics=computed(()=>{const k=overview.value?.kpis||overview.value?.metrics||overview.value||{};return [{label:'用户',value:scalar(k.users??k.jobseekers??k.total_users)},{label:'企业',value:scalar(k.enterprises??k.companies??k.total_enterprises)},{label:'岗位',value:scalar(k.jobs??k.total_jobs)},{label:'简历',value:scalar(k.resumes??k.total_resumes)}]})
const values=computed(()=>trend.value.map(x=>Number(x.count??x.value??x.jobs??0)))
const trendDots=computed(()=>{const max=Math.max(...values.value,1);return trend.value.slice(-7).map((x,i)=>({x:40+i*85,y:180-(Number(x.count??x.value??x.jobs??0)/max)*140,label:String(x.date||x.day||x.label||'').slice(-5)}))})
const trendPoints=computed(()=>trendDots.value.map(p=>`${p.x},${p.y}`).join(' '))
const maxJob=computed(()=>Math.max(...jobs.value.map(x=>Number(x.count??x.value??x.views??0)),1))
const barWidth=row=>Math.max(4,Number(row.count??row.value??row.views??0)/maxJob.value*100)
const funnelRows=computed(()=>{const rows=Object.entries(funnel.value||{}).map(([label,v])=>({label,value:typeof v==='object'?(v.count??v.value??0):v}));const max=Math.max(...rows.map(x=>Number(x.value)||0),1);return rows.map(x=>({...x,width:Math.max(18,Number(x.value)/max*100)}))})
async function load(){loading.value=true;error.value='';try{const [a,b,c,d]=await Promise.all([request({url:'/api/admin/analytics/overview'}),request({url:'/api/admin/analytics/trend?days=30'}),request({url:'/api/admin/analytics/jobs?top=10'}),request({url:'/api/admin/analytics/funnel'})]);overview.value=unwrap(a);trend.value=Array.isArray(unwrap(b))?unwrap(b):unwrap(b).items||unwrap(b).rows||[];jobs.value=Array.isArray(unwrap(c))?unwrap(c):unwrap(c).items||unwrap(c).rows||[];funnel.value=unwrap(d)}catch(e){error.value=e.message||'数据大屏暂不可用'}finally{loading.value=false}}
onMounted(load)
</script>
<style scoped>
.admin-board{padding:30rpx;background:linear-gradient(180deg,#f5f8ff 0%,#f7fafc 45%,#f2f7f5 100%);min-height:100%;display:flex;flex-direction:column;gap:22rpx}.board-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16rpx}.board-kicker{display:block;color:#6b7ca4;font-size:17rpx;letter-spacing:3rpx;font-weight:700}.board-title{display:block;font-size:46rpx;font-weight:850;line-height:1.2;color:#17233c;margin-top:5rpx}.board-sub{display:block;font-size:22rpx;color:#71809a;margin-top:8rpx}.refresh-btn{margin:0;border-radius:12rpx;background:#fff!important;color:#315ed5!important;border:1rpx solid #d8e1f5}.board-error{padding:18rpx;border-radius:14rpx;background:#fff0f0;color:#b43c31}.board-loading{color:#60708e;padding:25rpx;text-align:center}.board-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16rpx}.metric-card{position:relative;overflow:hidden;padding:22rpx;border-radius:22rpx;border:1rpx solid rgba(40,70,130,.08);background:#fff;box-shadow:0 8rpx 24rpx rgba(38,62,112,.07)}.metric-card::after{content:'';position:absolute;right:-24rpx;top:-28rpx;width:100rpx;height:100rpx;border-radius:50%;background:rgba(37,99,235,.08)}.metric-1::after{background:rgba(124,58,237,.09)}.metric-2::after{background:rgba(5,150,105,.09)}.metric-3::after{background:rgba(245,158,11,.11)}.metric-icon{width:48rpx;height:48rpx;border-radius:15rpx;background:#eaf1ff;color:#2563eb;display:flex;align-items:center;justify-content:center;font-size:23rpx;font-weight:800}.metric-1 .metric-icon{background:#f1eaff;color:#7c3aed}.metric-2 .metric-icon{background:#e5f8f0;color:#059669}.metric-3 .metric-icon{background:#fff4dd;color:#d97706}.metric-label{display:block;margin-top:15rpx;color:#687792;font-size:21rpx}.board-value{display:block;margin-top:4rpx;font-size:42rpx;font-weight:850;color:#18253e}.metric-caption{display:block;color:#9aa7bc;font-size:17rpx;margin-top:4rpx}.board-section{padding:24rpx;border:1rpx solid rgba(40,70,130,.08);border-radius:22rpx;background:#fff;box-shadow:0 8rpx 24rpx rgba(38,62,112,.05);display:flex;flex-direction:column;gap:14rpx}.section-head{display:flex;justify-content:space-between;align-items:flex-start}.board-section-title{display:block;font-size:29rpx;font-weight:800;color:#1d2a43}.section-sub{display:block;font-size:19rpx;color:#8795aa;margin-top:5rpx}.section-badge{font-size:16rpx;color:#2563eb;background:#eaf1ff;padding:7rpx 10rpx;border-radius:8rpx;font-weight:800}.section-badge.purple{color:#7c3aed;background:#f0eaff}.section-badge.green{color:#059669;background:#e5f8f0}.line-chart{width:100%;height:240rpx}.line-chart text{font-size:18px;fill:#64748b}.bar-row{display:flex;align-items:center;gap:9rpx}.rank{width:32rpx;color:#9aa7bc;font-size:18rpx}.bar-label{width:150rpx;font-size:21rpx;color:#4b5b75;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.bar-track{height:15rpx;flex:1;background:#edf1f8;border-radius:99rpx;overflow:hidden}.bar-fill{height:100%;background:linear-gradient(90deg,#4779e8,#8eb0ff);border-radius:99rpx}.bar-value{width:42rpx;text-align:right;color:#536683;font-size:20rpx}.empty-text{color:#9aa7bc;font-size:21rpx;text-align:center;padding:22rpx}.funnel-row{height:52rpx;background:#edf1f8;border-radius:10rpx;overflow:hidden;color:#fff;font-size:21rpx;line-height:52rpx}.funnel-row view{height:100%;padding:0 18rpx;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(90deg,#7954d9,#a78bfa);border-radius:10rpx;box-sizing:border-box}
</style>
